import { useEffect, useRef, useState } from "react";
import { AssistantMessage, Reasoning, type AiMessage } from "../../ai/index.js";
import { SectionPage, Specimen } from "../kit.js";
import { Button } from "../../ui/button/index.js";
import { MODEL, NOW } from "../sections/ai.fixtures.js";
import { AiGallery } from "../sections/ai.kit.js";

const STREAM =
  "The spooler has been running since **10:12 am** and the queue on the Level 2 Ricoh is empty. Mira printed two documents in the last ten minutes; both completed.";
const base = (extra: Partial<AiMessage>): AiMessage => ({
  id: "x",
  role: "assistant",
  createdAt: NOW - 60000,
  state: "complete",
  model: MODEL.name,
  blocks: [],
  ...extra,
});

function StreamingDemo() {
  const [text, setText] = useState("");
  const [running, setRunning] = useState(false);
  const timer = useRef<ReturnType<typeof setInterval> | undefined>(undefined);
  useEffect(() => () => clearInterval(timer.current), []);
  const start = () => {
    clearInterval(timer.current);
    const words = STREAM.split(/(?<=\s)/);
    let index = 0;
    setText("");
    setRunning(true);
    timer.current = setInterval(() => {
      index += 1;
      setText(words.slice(0, index).join(""));
      if (index >= words.length) {
        clearInterval(timer.current);
        setRunning(false);
      }
    }, 60);
  };
  return (
    <div className="ai-stack">
      <AssistantMessage
        latest
        message={base({
          id: "stream",
          state: running ? "streaming" : "complete",
          blocks: [
            { kind: "markdown", text: text || "Press Stream to watch the caret append in place." },
          ],
        })}
        activity={running && !text ? { state: "working", model: MODEL.name } : undefined}
      />
      <div>
        <Button
          size="sm"
          onClick={start}
          status={running ? "pending" : undefined}
          pendingLabel="Streaming…"
        >
          Stream an answer
        </Button>
      </div>
    </div>
  );
}

export default function AiMessagesSection() {
  return (
    <AiGallery>
      <SectionPage>
        <Specimen
          title="Reasoning and streaming"
          description="The reasoning summary folds to one line with the time it took. Streaming text appends after a static caret; earlier lines never reflow."
          layout="stack"
          specimenKey="ai-messages:default:5"
        >
          <Reasoning
            reasoning={{
              seconds: 4,
              summary:
                "Find the organisation, list its offline endpoints, keep those silent for more than a day, then look for a shared site or time.",
            }}
          />
          <Reasoning
            reasoning={{
              seconds: 2,
              running: true,
              summary: "Reading the spooler events on NST-C106…",
            }}
            defaultOpen
          />
          <StreamingDemo />
        </Specimen>
      </SectionPage>
    </AiGallery>
  );
}
